(x, y, t) => {
  let u = x / 480, v = y / 240, T = t * 0.3;
  let ca = 0, cb = 0, cc = 0;
  for (let i = 1; i <= 6; i++) {
    let f = i * 2.1 + 0.5, ph = T * (0.25 + i * 0.12);
    ca += Math.sin(u * f * 1.6 + v * f * 0.7 + ph) / i;
    cb += Math.cos(u * f * 0.9 - v * f * 1.5 + ph * 1.15) / i;
    cc += Math.sin((u + v) * f * 0.8 - ph * 0.9 + u * f * 0.3) / i;
  }
  let rA = ca * ca - cb * cb + 0.5 * ca * cc;
  let rB = cb * cb - cc * cc + 0.4 * cb * ca;
  let rC = cc * cc - ca * ca + 0.35 * cc * cb;
  let diff = Math.sin(rA * 4.2 + T) * Math.cos(rB * 3.8 - T * 0.6) * Math.sin(rC * 2.5 + T * 0.8);
  let spots = Math.sin((rA + diff) * 14.0 + Math.sin(rB * 3.5) * 2.5);
  let maze = Math.sin((rB + diff * 0.7) * 10.0 + Math.cos(rC * 4.0 + T) * 2.0);
  let mitosis = Math.sin((rC + diff * 0.5) * 8.0 + Math.sin(rA * 5.0 - T * 0.5) * 1.8);
  let p = spots * 0.4 + maze * 0.35 + mitosis * 0.25;
  let edge = 1.0 / (1.0 + Math.exp(p * -5.5));
  let inner = 1.0 / (1.0 + Math.exp((p - 0.15) * -6.0));
  let glow = 1.0 / (1.0 + Math.exp((p + 0.2) * -4.0));
  let detail = Math.sin(u * 47 + v * 31 + T * 2.0) * Math.cos(v * 37 - u * 23 - T * 1.5) * 0.08;
  let hue = Math.atan2(rB, rA) * 0.5 + 0.5 + detail;
  let sat = 0.7 + 0.3 * inner;
  let val = 0.15 + 0.65 * edge + 0.2 * glow;
  let h6 = hue * 6.0;
  let hi = Math.floor(h6) % 6, hf = h6 - Math.floor(h6);
  let pp = val * (1 - sat), qq = val * (1 - hf * sat), tt2 = val * (1 - (1 - hf) * sat);
  let rr, gg, bb;
  if (hi === 0) { rr = val; gg = tt2; bb = pp; }
  else if (hi === 1) { rr = qq; gg = val; bb = pp; }
  else if (hi === 2) { rr = pp; gg = val; bb = tt2; }
  else if (hi === 3) { rr = pp; gg = qq; bb = val; }
  else if (hi === 4) { rr = tt2; gg = pp; bb = val; }
  else { rr = val; gg = pp; bb = qq; }
  let warm = edge * glow * 0.15;
  return [
    Math.min(1, Math.max(0, rr + warm * 1.2)),
    Math.min(1, Math.max(0, gg + warm * 0.5)),
    Math.min(1, Math.max(0, bb + warm * 0.3))
  ];
}
